      url: {
        %context%: true
        %timefield%: @timestamp
        index: .internal.alerts-observability.threshold.alerts*,-.internal.alerts-observability.threshold.alerts-default-000022,-.internal.alerts-observability.threshold.alerts-default-000023
        body: {
