                bool: {
                  must: [
                    {
                      range: {
                        kibana.alert.start: {
                          lte: now-7d
                        }
                      }
                    }
                  ]
                  should: [
                    {
                      term: {
                        kibana.alert.status: active
                      }
                    }
                    {
                      range: {
                        kibana.alert.end: {
                          gte: now-14d
                          lt: now-7d
                        }
                      }
                    }
                  ]
                  minimum_should_match: 1
