}"},"uiState":{},"data":{"aggs":[],"searchSource":{"query":{"query":"","language":"kuery"},"filter":[]}}},"drilldowns":[{"label":"Go to Alerts Drilldown","trigger":"on_open_panel_menu","open_in_new_tab":true,"encode_url":true,"url":"{{kibanaUrl}}/app/dashboards#/view/4467884c-10c8-4128-8a51-901f258b8695?_g=(filters:!({{rison context.panel.filters}},(query:(match_phrase:(kibana.alert.status:'active')))),time:(from:'{{context.panel.timeRange.from}}',to:'{{context.panel.timeRange.to}}'))","type":"url_drilldown"}]},"panelIndex":"1d9ec5d0-9ab3-4f12-9163-9c8cde014db5","gridData":{"y":0,"x":27,"w":6,"h":7,"i":"1d9ec5d0-9ab3-4f12-9163-9c8cde014db5","sectionId":"f92d84c2-6bc0-496c-8cf7-a3899bf9a193"}},{"type":"legacy_vis","embeddableConfig":{"description":"Portfolio Health% measures the proportion of transactions that were successfully served relative to total requests across all applications in the selected portfolio. This KPI helps monitor service health, reliability, and overall user experience.","savedVis":{"title":"","description":"","type":"vega","params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "autosize": {
    "type": "fit",
    "contains": "padding",
    "resize": true
  },
  "padding": {
    "top": 8,
    "right": 10,
    "bottom": 8,
    "left": 10
  },
  "config": {
    "background": "transparent",
    "font": "Arial"
  },
  "signals": [
    {
      "name": "hasData",
      "update": "data('availability').length > 0 && data('availability')[0].total_count.doc_count > 0"
    },
    {
      "name": "cx",
      "update": "width / 2"
    },
    {
      "name": "cy",
      "update": "height * 0.39"
    },
    {
      "name": "radius",
      "update": "min(width, height) * 0.27"
    },
    {
      "name": "innerRadius",
      "update": "radius * 0.79"
    },
    {
      "name": "startAngle",
      "value": -2.35619449
    },
    {
      "name": "endAngle",
      "value": 2.35619449
    },
    {
      "name": "availability",
      "update": "hasData ? data('availability')[0].availability : 0"
    },
    {
      "name": "clampedAvailability",
      "update": "clamp(availability, 95, 100)"
    },
    {
      "name": "valueAngle",
      "update": "startAngle + ((clampedAvailability - 95) / 5) * (endAngle - startAngle)"
    },
    {
      "name": "status",
      "update": "!hasData ? 'NO DATA' : availability >= 99.5 ? 'HEALTHY' : availability >= 99 ? 'WARNING' : 'CRITICAL'"
    },
    {
      "name": "statusColor",
      "update": "!hasData ? '#9CA3AF' : availability >= 99.5 ? '#36B37E' : availability >= 99 ? '#FFAB00' : '#DE350B'"
    },
    {
      "name": "current24h",
      "update": "data('current24h').length > 0 && data('current24h')[0].total_count.doc_count > 0 ? data('current24h')[0].availability : null"
    },
    {
      "name": "previous24h",
      "update": "data('previous24h').length > 0 && data('previous24h')[0].total_count.doc_count > 0 ? data('previous24h')[0].availability : null"
    },
    {
      "name": "hasComparison",
      "update": "isValid(current24h) && isValid(previous24h) && previous24h > 0"
    },
    {
      "name": "roundedCurrent24h",
      "update": "isValid(current24h) ? round(current24h * 100) / 100 : null"
    },
    {
      "name": "roundedPrevious24h",
      "update": "isValid(previous24h) ? round(previous24h * 100) / 100 : null"
    },
    {
      "name": "pctChange",
      "update": "hasComparison && roundedPrevious24h > 0 ? ((roundedCurrent24h - roundedPrevious24h) / roundedPrevious24h) * 100 : 0"
    },
    {
      "name": "roundedPctChange",
      "update": "round(pctChange * 100) / 100"
    },
    {
      "name": "changeColor",
      "update": "!hasComparison ? '#9CA3AF' : roundedPctChange > 0 ? '#36B37E' : roundedPctChange < 0 ? '#DE350B' : '#9CA3AF'"
    },
    {
      "name": "titleSize",
      "update": "clamp(min(width, height) * 0.055, 12, 15)"
    },
    {
      "name": "valueSize",
      "update": "clamp(min(width, height) * 0.075, 19, 30)"
    },
    {
      "name": "statusSize",
      "update": "clamp(min(width, height) * 0.027, 9, 11)"
    },
    {
      "name": "comparisonSize",
      "update": "clamp(min(width, height) * 0.035, 10, 12)"
    },
    {
      "name": "detailSize",
      "update": "clamp(min(width, height) * 0.028, 9, 10)"
    },
    {
      "name": "legendSize",
      "update": "clamp(min(width, height) * 0.029, 9, 11)"
    },
    {
      "name": "titleY",
      "update": "12"
    },
    {
      "name": "comparisonY",
      "update": "height * 0.70"
    },
    {
      "name": "detailY",
      "update": "height * 0.77"
    },
    {
      "name": "legendTitleY",
      "update": "height * 0.84"
    },
    {
      "name": "legendValueY",
      "update": "height * 0.90"
    },
    {
      "name": "legendStatusY",
      "update": "height * 0.96"
    },
    {
      "name": "legendDotSize",
      "update": "clamp(min(width, height) * 0.008, 28, 45)"
    }
  ],
  "data": [
    {
      "name": "availability",
      "url": {
        "%context%": true,
        "%timefield%": "@timestamp",
        "index": "traces-apm*",
        "body": {
          "size": 0,
          "aggs": {
            "success_count": {
              "filter": {
                "bool": {
                  "must": [
                    {
                      "term": {
                        "event.outcome": "success"
                      }
                    }
                  ],
                  "must_not": [
                    {
                      "wildcard": {
                        "transaction.name": "google*"
                      }
                    }
                  ]
                }
              }
            },
            "server_error_count": {
              "filter": {
                "bool": {
                  "must": [
                    {
                      "range": {
                        "http.response.status_code": {
                          "gte": 500
                        }
                      }
                    }
                  ],
                  "must_not": [
                    {
                      "wildcard": {
                        "transaction.name": "google*"
                      }
                    }
                  ]
                }
              }
            },
            "total_count": {
              "filter": {
                "bool": {
                  "must_not": [
                    {
                      "wildcard": {
                        "transaction.name": "google*"
                      }
                    }
                  ]
                }
              }
            }
